///|
async fn publish_file(path : String, content : String) -> Unit {
  @fs.write_file(path + ".tmp", content, permission=0o600)
  @fs.rename(path + ".tmp", path, replace=true)
}

///|
async fn supervisor_alive(directory : String) -> Bool {
  let lock = @fs.open(
    directory + "/supervisor.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn ensure_supervisor(initial_workspace? : String) -> Unit {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let startup = @fs.open(
    directory + "/supervisor-startup.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer startup.close()
  @async.with_timeout(10000, async fn() {
    while !startup.try_lock(Exclusive) {
      @async.sleep(10)
    }
    if supervisor_alive(directory) {
      save_diagnostic("supervisor-launch", "reused", evidence={
        "stateDirectory": directory,
      })
      return
    }
    let sink = @process.redirect_to_file("/dev/null", shared=true)
    defer sink.close()
    ignore(
      @process.spawn_orphan(
        saved_proxy_executable(),
        ["--supervisor", directory] +
        initial_workspace.map(value => [value]).unwrap_or([]),
        stdin=@process.redirect_from_file("/dev/null"),
        stdout=sink,
        stderr=sink,
      ),
    )
    while !supervisor_alive(directory) {
      @async.sleep(10)
    }
  })
}

///|
pub async fn supervisor(
  directory : String,
  initial_workspace? : String,
) -> Unit {
  guard directory == adapter_state_home() else {
    raise AdapterError("Supervisor state directory mismatch")
  }
  let lock = @fs.open(
    directory + "/supervisor.lock",
    mode=ReadWrite,
    create_mode=OpenOrCreate,
    permission=0o600,
  )
  defer lock.close()
  if !lock.try_lock(Exclusive) {
    return
  }
  publish_file(directory + "/supervisor.pid", proxy_pid().to_string())

  let mut released = false
  defer (if !released {
    @fs.remove(directory + "/supervisor.pid") catch {
      _ => ()
    }
  })
  save_diagnostic("supervisor", "started", evidence={
    "stateDirectory": directory,
  })
  defer save_diagnostic("supervisor", "stopped")
  let listener = @socket.TcpServer(@socket.Addr::parse("127.0.0.1:0"))
  defer listener.close()
  let identity : Json = {
    "protocol": 1,
    "pid": proxy_pid().to_string(),
    "start": process_start(proxy_pid()).to_string(),
  }
  let descriptor : Json = {
    "pid": required(identity, "pid"),
    "start": required(identity, "start"),
    "port": listener.addr.port().to_string(),
  }
  publish_file(directory + "/supervisor.json", descriptor.stringify())
  let environments : Map[String, Map[String, String]] = Map([])
  if initial_workspace is Some(workspace) {
    let canonical = @fs.realpath(workspace)
    guard canonical.has_prefix(@fs.realpath(directory) + "/tunnels/") else {
      raise AdapterError("Initial workspace is outside the state directory")
    }
    environments.set(canonical, @env.get_env_vars())
  }
  let registrations : Ref[Int32] = { val: 0, }
  let active : Map[String, Bool] = Map([])
  let finished : Map[String, Bool] = Map([])
  let transports : Map[String, Bool] = Map([])
  let mut idle_since = @env.now()
  @async.with_task_group(async fn(group) {
    let registration_slots = @async.Semaphore(16)
    group.spawn_bg(no_wait=true, async fn() {
      while true {
        registration_slots.acquire()
        let (socket, _) = listener.accept()
        registrations.val += 1
        group.spawn_bg(no_wait=true, async fn() {
          defer {
            registrations.val -= 1
            registration_slots.release()
          }
          accept_registration(socket, directory, environments, identity) catch {
            error =>
              save_diagnostic(
                "supervisor-registration",
                "failed",
                error_type="registration_failed",
                error_message=redact_credentials(error.to_string()),
              )
          }
        })
      }
    })
    while @fs.exists(directory) {
      for workspace in finished.keys().to_array() {
        if !@fs.exists(workspace) {
          finished.remove(workspace)
        }
      }
      for workspace in environments.keys().to_array() {
        if !@fs.exists(workspace) {
          environments.remove(workspace)
        }
      }
      let base = directory + "/tunnels"
      if @fs.exists(base) {
        for name in @fs.readdir(base) {
          let workspace = base + "/" + name
          try {
            let requested = @fs.exists(workspace + "/request")
            if finished.contains(workspace) && !requested {
              continue
            }
            let canonical = @fs.realpath(workspace)
            guard environments.get(canonical) is Some(environment) else {
              continue
            }
            if active.contains(workspace) ||
              !@fs.exists(workspace + "/enabled") ||
              !@fs.exists(workspace + "/state.json") {
              continue
            }
            if requested {
              @fs.remove(workspace + "/request")
            }
            active.set(workspace, true)
            group.spawn_bg(no_wait=true, async fn() {
              defer {
                active.remove(workspace)
                finished.set(workspace, true)
              }
              try {
                save_diagnostic(
                  "supervisor-workspace",
                  "started",
                  tunnel_directory=workspace,
                )
                if !worker_alive(workspace) {
                  tunnel_status(workspace, "connecting")
                  git_relay_status(workspace, "pending")
                }
                tunnel_worker(workspace, environment)
                save_diagnostic(
                  "supervisor-workspace",
                  "stopped",
                  tunnel_directory=workspace,
                )
              } catch {
                error => {
                  save_diagnostic(
                    "supervisor-workspace",
                    "failed",
                    tunnel_directory=workspace,
                    error_type="workspace_task_failed",
                    error_message=redact_credentials(error.to_string()),
                  )
                  @async.sleep(1000)
                }
              }
            })
          } catch {
            error =>
              save_diagnostic(
                "supervisor-workspace",
                "failed",
                tunnel_directory=workspace,
                error_type="workspace_registration_failed",
                error_message=redact_credentials(error.to_string()),
              )
          }
        }
      }
      let base = directory + "/transports"
      if @fs.exists(base) {
        for name in @fs.readdir(base) {
          let transport = base + "/" + name
          if transports.contains(transport) ||
            !@fs.exists(transport + "/state.json") ||
            @fs.exists(transport + "/done") {
            continue
          }
          transports.set(transport, true)
          group.spawn_bg(no_wait=true, async fn() {
            defer transports.remove(transport)
            supervise_transport(transport) catch {
              error =>
                save_diagnostic(
                  "supervisor-transport",
                  "failed",
                  error_type="transport_cleanup_failed",
                  error_message=redact_credentials(error.to_string()),
                )
            }
          })
        }
      }
      if !active.is_empty() || !transports.is_empty() || registrations.val > 0 {
        idle_since = @env.now()
      } else if @env.now() - idle_since >= 1000 {
        let startup = @fs.open(
          directory + "/supervisor-startup.lock",
          mode=ReadWrite,
          create_mode=OpenOrCreate,
          permission=0o600,
        )
        defer startup.close()
        if startup.try_lock(Exclusive) &&
          !supervisor_pending(directory, finished, environments) {
          listener.close()
          @fs.remove(directory + "/supervisor.json")
          @fs.remove(directory + "/supervisor.pid")
          released = true
          lock.unlock()
          return
        }
      }
      @async.sleep(100)
    }
  })
}

///|
async fn supervise_transport(directory : String) -> Unit {
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  let pid = @string.parse_int(required(state, "pid"))
  guard pid > 1 else { raise AdapterError("Invalid transport owner") }
  let owner = @fs.open(directory + "/owner.lock", mode=ReadWrite)
  defer owner.close()
  let start = @string.parse_int64(required(state, "start"))
  save_diagnostic("supervisor-transport", "started", evidence={ "pid": pid })
  let reason : Ref[String] = { val: "supervisor_shutdown", }
  defer @async.protect_from_cancel(async fn() {
    if transport_group_alive(pid, start) {
      if reason.val != "transport_exited" {
        ignore(proxy_signal(-pid, 15))
        @async.sleep(500)
      }
      if transport_group_alive(pid, start) {
        ignore(proxy_signal(-pid, 9))
        @async.with_timeout(2000, async fn() {
          while transport_group_alive(pid, start) {
            @async.sleep(10)
          }
        })
      }
    }
    let exit_code = if @fs.exists(directory + "/exited") {
      Some(@string.parse_int(@fs.read_file(directory + "/exited").text()))
    } else {
      None
    }
    save_diagnostic(
      "ssh-proxy",
      if reason.val != "transport_exited" {
        "cancelled"
      } else if exit_code == Some(0) {
        "success"
      } else {
        "failed"
      },
      exit_code?,
      error_type?=exit_code
        .filter(code => code != 0)
        .map(code => if code < 0 { "process_signal" } else { "process_exit" }),
      evidence={ "pid": pid, "transport": directory, "reason": reason.val },
    )
    publish_file(directory + "/done", reason.val)
    if owner.try_lock(Exclusive) {
      @fs.rmdir(directory, recursive=true)
    }
    save_diagnostic("supervisor-transport", "stopped", evidence={
      "pid": pid,
      "reason": reason.val,
    })
  })
  while true {
    let abandoned = owner.try_lock(Exclusive)
    let exited = @fs.exists(directory + "/exited")
    let eof = if @fs.exists(directory + "/eof") {
      @env.now() >=
      @string.parse_uint64(@fs.read_file(directory + "/eof").text()) + 1000
    } else {
      false
    }
    if abandoned || exited || eof {
      reason.val = if abandoned {
        "owner_exited"
      } else if exited {
        "transport_exited"
      } else {
        "stdin_eof"
      }
      return
    }
    @async.sleep(100)
  }
}

///|
async fn supervisor_pending(
  directory : String,
  finished : Map[String, Bool],
  environments : Map[String, Map[String, String]],
) -> Bool {
  let base = directory + "/tunnels"
  if @fs.exists(base) {
    for name in @fs.readdir(base) {
      let workspace = base + "/" + name
      if environments.contains(@fs.realpath(workspace)) &&
        @fs.exists(workspace + "/enabled") &&
        @fs.exists(workspace + "/state.json") &&
        (!finished.contains(workspace) || @fs.exists(workspace + "/request")) {
        return true
      }
    }
  }
  let base = directory + "/transports"
  if @fs.exists(base) {
    for name in @fs.readdir(base) {
      if @fs.exists(base + "/" + name + "/state.json") &&
        !@fs.exists(base + "/" + name + "/done") {
        return true
      }
    }
  }
  false
}
///|
async fn read_registration(socket : @socket.Tcp, limit : Int32) -> Json {
  let header = @buffer.Buffer()
  while true {
    let byte = socket.read_exactly(1)
    if byte == b"\n" {
      break
    }
    guard header.length() < 8 else {
      raise AdapterError("Invalid registration length")
    }
    header.write_bytes(byte)
  }
  let length = @string.parse_int(@utf8.decode(header.to_bytes()))
  guard length > 0 && length <= limit else {
    raise AdapterError("Registration is too large")
  }
  @json.parse(@utf8.decode(socket.read_exactly(length))) catch {
    _ => raise AdapterError("Invalid registration JSON")
  }
}

///|
async fn write_registration(socket : @socket.Tcp, value : Json) -> Unit {
  let bytes = @utf8.encode(value.stringify())
  guard bytes.length() <= 4194304 else {
    raise AdapterError("Registration is too large")
  }
  socket.write(bytes.length().to_string() + "\n")
  socket.write(bytes)
}

///|
async fn register_workspace(directory : String) -> Unit {
  let mut detail = "Supervisor registration endpoint is not ready"
  @async.with_timeout(10000, async fn() {
    while true {
      try {
        ensure_supervisor(initial_workspace=directory)
        register_workspace_inner(directory)
        return
      } catch {
        error => detail = redact_credentials(error.to_string())
      }
      @async.sleep(100)
    }
  }) catch {
    @async.TimeoutError =>
      raise AdapterError("Workspace registration timed out: " + detail)
    error => raise error
  }
}

///|
async fn register_workspace_inner(directory : String) -> Unit {
  let path = adapter_state_home() + "/supervisor.json"
  let descriptor = @json.parse(@fs.read_file(path).text())
  let pid = @string.parse_int(required(descriptor, "pid"))
  let start = @string.parse_int64(required(descriptor, "start"))
  guard pid > 1 && start > 0 && process_start(pid) == start else {
    raise AdapterError("Supervisor registration endpoint is stale")
  }
  let port = @string.parse_int(required(descriptor, "port"))
  guard port > 0 && port <= 65535 else {
    raise AdapterError("Invalid supervisor port")
  }
  let socket = @socket.Tcp::connect(
    @socket.Addr::parse("127.0.0.1:" + port.to_string()),
  )
  defer socket.close()
  let peer = read_registration(socket, 4096)
  guard field(peer, "protocol") == Some(Json::number(1)) &&
    field(peer, "pid") == field(descriptor, "pid") &&
    field(peer, "start") == field(descriptor, "start") else {
    raise AdapterError("Supervisor registration endpoint changed")
  }
  let environment = Json::empty_object()
  for (name, value) in @env.get_env_vars() {
    set_field(environment, name, Json::string(value))
  }
  write_registration(socket, {
    "directory": directory,
    "environment": environment,
  })
  let reply = read_registration(socket, 4096)
  guard field(reply, "accepted") == Some(Json::boolean(true)) else {
    raise AdapterError("Supervisor rejected workspace registration")
  }
}

///|
async fn accept_registration(
  socket : @socket.Tcp,
  root : String,
  environments : Map[String, Map[String, String]],
  identity : Json,
) -> Unit {
  defer socket.close()
  @async.with_timeout(10000, async fn() {
    write_registration(socket, identity)
    let request = read_registration(socket, 4194304)
    let directory = @fs.realpath(required(request, "directory"))
    guard directory.has_prefix(@fs.realpath(root) + "/tunnels/") &&
      @fs.exists(directory + "/state.json") else {
      raise AdapterError(
        "Workspace registration is outside the state directory",
      )
    }
    guard field(request, "environment") is Some(Json::Object(values)) else {
      raise AdapterError("Missing workspace execution environment")
    }
    let environment : Map[String, String] = Map([])
    for (name, value) in values {
      guard value is Json::String(value) else {
        raise AdapterError("Invalid workspace execution environment")
      }
      environment.set(name, value)
    }
    environments.set(directory, environment)
    save_diagnostic(
      "supervisor-registration",
      "success",
      tunnel_directory=directory,
    )
    write_registration(socket, { "accepted": true })
  })
}
